    'regular mail service within canada' => '캐나다 내 정기 우편물 서비스',
    'tracking <strong>not</strong> available' => '추적 불가',
    'regular mail service international' => '국제 정기 우편물 서비스',
    'courier service within canada' => '캐나다 내 택배 서비스',
